<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Support,Database,Core,Authorization,Accounts,Documents,Audit};
final class Web {
 public function __construct(private \PDO $p,private ?array $user){}
 private function actor():int {if(!$this->user)Support::redirect('/login');return (int)$this->user['id'];}
 private static function e(mixed $s):string{return Support::escape($s);}
 private static function field(string $key,string $label,mixed $v='',string $type='text',bool $required=true):string {return '<label>'.self::e($label).'<input name="'.self::e($key).'" type="'.$type.'" value="'.self::e($v).'"'.($required?' required':'').'></label>';}
 private static function area(string $k,string $label,string $v=''):string{return '<label>'.self::e($label).'<textarea name="'.$k.'" rows="4">'.self::e($v).'</textarea></label>';}
 private static function select(string $k,string $label,array $rows,mixed $value='',bool $multiple=false):string {$h='<label>'.self::e($label).'<select name="'.$k.($multiple?'[]':'').'"'.($multiple?' multiple size="5"':'').'>';if(!$multiple)$h.='<option value="">Pilih</option>';foreach($rows as $id=>$name)$h.='<option value="'.self::e($id).'"'.(($multiple?in_array((string)$id,array_map('strval',(array)$value),true):(string)$id===(string)$value)?' selected':'').'>'.self::e($name).'</option>';return $h.'</select></label>';}
 private static function form(string $action,string $fields,string $button='Simpan',bool $file=false):string{return '<form method="post"'.($file?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.$action.'">'.$fields.'<button>'.$button.'</button></form>';}
 private static function hidden(string $key,mixed $v):string{return '<input type="hidden" name="'.$key.'" value="'.self::e($v).'">';}
 private function options(string $sql,array $args=[]):array {$out=[];foreach(Database::query($this->p,$sql,$args)->fetchAll() as $r)$out[$r['id']]=$r['name'];return $out;}
 private function page(string $title,string $h,string $message=''):never {Support::layout($title,'<nav class="actions"><a href="/dashboard">Shared Core</a><a href="/training">Program</a><a href="/training/portal">Aktiviti / Galeri</a><a href="/training/history">My Training</a><a href="/training/mine">Pendaftaran saya</a>'.($this->user?'<a href="/training/new">Cipta program</a>':'<a href="/login">Log masuk</a>').($this->user&&Authorization::super($this->p,$this->actor())?'<a href="/training/setup">Upgrade</a>':'').'</nav>'.($message?'<p class="notice" role="status">'.self::e($message).'</p>':'').$h);}
 private function id():int{return Core::id($_GET['id']??$_POST['programme_id']??'');}
 public function handle(string $path):never {
  if($path==='/training/setup')$this->setup();
  if(!Migrations::ready($this->p)){http_response_code(503);$this->page('Modul belum dipasang','<p>Shared Core kekal tersedia. Super Admin perlu melengkapkan Setup T1.</p>');}
  Core::module($this->p,'training');$message='';
  try{
   if($path==='/training/invite'&&isset($_GET['token'])){$token=Core::text($_GET['token'],64);if(!preg_match('/\A[a-f0-9]{64}\z/',$token))throw new \RuntimeException('Jemputan tidak sah.');$_SESSION['training_pending']=['token'=>$token];Support::redirect($this->user?'/training/invite':'/login');}
   if($path==='/training/register'&&!$this->user){$_SESSION['training_pending']=['key'=>Core::text($_GET['key']??'',32)];Support::redirect('/login');}
   if($_SERVER['REQUEST_METHOD']==='POST'){Support::checkCsrf();$message=$this->action(Support::post('action',40));}
   if($path==='/training/qr'){$link=Tokens::resolve($this->p,Core::text($_GET['key']??'',32));header('Content-Type: image/svg+xml');echo Qr::svg(Accounts::origin().'/training/register?key='.$link['public_key']);exit;}
   $h=match($path){'/training'=>$this->listing(),'/training/new'=>$this->editor(),'/training/edit'=>$this->editor($this->id()),'/training/manage'=>$this->manage($this->id()),'/training/p'=>$this->publicPage($this->id()),'/training/register'=>$this->registrationLink(),'/training/invite'=>$this->invitationPage(),'/training/mine'=>$this->mine(),default=>throw new \RuntimeException('Halaman tidak ditemui.')};
   $this->page('Training — Programme & Registration',$h,$message);
  }catch(\PDOException $e){http_response_code(500);$this->page('Ralat sistem','<p>Rujukan: '.self::e(Support::log($e)).'</p>');}catch(\RuntimeException|\InvalidArgumentException $e){if(http_response_code()<400)http_response_code(400);$this->page('Permintaan tidak tersedia','<p class="error">'.self::e($e->getMessage()).'</p>');}
 }
 private function setup():never {$u=$this->actor();if(!Authorization::super($this->p,$u)){http_response_code(403);throw new \RuntimeException('Super Admin diperlukan.');}if($_SERVER['REQUEST_METHOD']==='POST')Support::checkCsrf();Support::redirect('/upgrade');}
 private function action(string $action):string {
  $u=$this->actor();$p=$this->p;$id=Core::id($_POST['programme_id']??null,true);
  switch($action){
   case 'save':$d=$_POST;foreach(['start_at','end_at','open_at','close_at'] as $k){$tz=new \DateTimeZone(Core::text($d['timezone']??'Asia/Kuala_Lumpur',64));$dt=\DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$d[$k]??'',$tz);if(!$dt||$dt->format('Y-m-d\TH:i')!==$d[$k])throw new \RuntimeException('Tarikh tidak sah.');$d[$k]=$dt->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');}$d['eligibility']=[];foreach(['profession','position','grade','employment_status'] as $k)$d['eligibility'][$k]=$d[$k.'_ids']??[];$d['quotas']=[];foreach($d['quota_kind']??[] as $n=>$kind)if($kind!=='')$d['quotas'][]=['kind'=>$kind,'id'=>$d['quota_id'][$n]??'','limit'=>$d['quota_limit'][$n]??''];$new=Programmes::save($p,$u,$d,$id);Support::redirect('/training/manage?id='.$new);
   case 'transition':Programmes::transition($p,$u,$id,Support::post('decision'),Core::id($_POST['revision_id']??''),Support::post('reason',500));return 'Status program disimpan.';
   case 'register':$a=Policy::actor($p,$u);Accounts::throttle($p,'training_registration',$this->user['email']);$rid=Registration::register($p,$u,$id,null,($_POST['walkin']??'')==='1'?'WALK_IN':'SELF',$_SESSION['training_pending']['token']??null,$_POST['link_key']??null);unset($_SESSION['training_pending']);return 'Pendaftaran #'.$rid.' direkod. Semak status dalam Pendaftaran saya.';
   case 'decision':Registration::decide($p,$u,$id,Core::id($_POST['registration_id']??''),Support::post('decision'),Support::post('reason',500));return 'Status pendaftaran disimpan.';
   case 'assign':$ids=$_POST['staff_ids']??[];if(!is_array($ids))throw new \RuntimeException('Pilihan tidak sah.');$out=Registration::bulk($p,$u,$id,$ids);$_SESSION['training_import_result']=$out;return 'Assignment diproses; semak laporan setiap baris.';
   case 'walkin_assign':Registration::register($p,$u,$id,Core::id($_POST['staff_identity_id']??''),'WALK_IN');return 'Walk-in direkod, bukan check-in.';
   case 'preview':$f=$_FILES['file']??[];if(($f['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']??'')||filesize($f['tmp_name'])>1024*1024||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='csv')throw new \RuntimeException('CSV maksimum 1 MB.');$rows=Registration::preview($p,$u,$id,file_get_contents($f['tmp_name']));$_SESSION['training_import']=['programme'=>$id,'expires'=>time()+1800,'rows'=>$rows];return 'Preview disediakan; tiada assignment dibuat.';
   case 'import_commit':$batch=$_SESSION['training_import']??null;if(!$batch||$batch['programme']!==$id||$batch['expires']<time())throw new \RuntimeException('Preview tamat tempoh.');$ids=[];foreach($batch['rows'] as $r)if(!$r['error'])$ids[]=$r['staff_identity_id'];unset($_SESSION['training_import']);$_SESSION['training_import_result']=$ids?Registration::bulk($p,$u,$id,$ids):[];return 'Import valid rows diproses.';
   case 'invite':$url=Tokens::invite($p,$u,$id,Core::id($_POST['staff_identity_id']??''));$_SESSION['training_invite_url']=$url;return 'Jemputan queued; penghantaran bergantung SMTP.';
   case 'invite_revoke':Tokens::revoke($p,$u,$id,Core::id($_POST['invitation_id']??''));return 'Jemputan dibatalkan.';
   case 'link':Tokens::link($p,$u,$id);return 'Link lama dinyahaktifkan. Link baharu tersedia.';
   case 'grant':Roles::grant($p,$u,$id,Core::id($_POST['user_id']??''),Core::id($_POST['role_id']??''),Support::post('expires_at'),Support::post('reason',500));return 'Role program diberikan.';
   case 'revoke':Roles::revoke($p,$u,$id,Core::id($_POST['assignment_id']??''),Support::post('reason',500));return 'Role program dibatalkan.';
   case 'role_define':Roles::definition($p,$u,$id,Support::post('code',64),Support::post('name',100));return 'Role penyertaan disimpan.';
   case 'participation':Roles::participation($p,$u,$id,Core::id($_POST['registration_id']??''),Core::id($_POST['role_id']??''),($_POST['remove']??'')==='1');return 'Role penyertaan disimpan.';
   case 'document':$r=Policy::programme($p,$id);Documents::upload($p,$u,(int)$r['owner_organisation_id'],'training',Support::post('title',190),$_FILES['file']??[],Core::id($_POST['document_id']??null,true),$id);return 'Dokumen program disimpan.';
   default:throw new \RuntimeException('Tindakan tidak sah.');
  }
 }
 private function listing():string {
  $h='<h2>Program diterbitkan</h2>';foreach(Database::query($this->p,'SELECT id FROM training_programmes WHERE is_published=1 AND is_cancelled=0 ORDER BY id DESC')->fetchAll() as $row){try{$r=Policy::programme($this->p,(int)$row['id']);$c=Policy::config($this->p,$r,true);$h.='<section class="card"><h3>'.self::e($c['title']).'</h3><p>'.self::e($c['type'].' · '.$c['mode'].' · '.$c['start_at'].' UTC').'</p><a href="/training/p?id='.$r['id'].'">Maklumat & pendaftaran</a></section>';}catch(\RuntimeException $e){continue;}}
  if($this->user){$h.='<h2>Program di bawah akses saya</h2>';foreach(Database::query($this->p,'SELECT id FROM training_programmes ORDER BY id DESC')->fetchAll() as $row){try{$r=Policy::programme($this->p,(int)$row['id']);if(!Policy::allowed($this->p,$this->actor(),'programmes.view',$r))continue;$c=Policy::config($this->p,$r);$h.='<p><a href="/training/manage?id='.$r['id'].'">'.self::e($c['title']).'</a> · '.self::e($r['status']).'</p>';}catch(\RuntimeException $e){continue;}}}return $h;
 }
 private function editor(?int $id=null):string {
  $u=$this->actor();$c=[];$owner='';if($id){$r=Policy::programme($this->p,$id);Policy::require($this->p,$u,'programmes.edit',$r);$c=Policy::config($this->p,$r);$owner=$r['owner_organisation_id'];}else{Policy::actor($this->p,$u);}
  $orgs=$this->options('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name');$owners=[];foreach($orgs as $o=>$name)if(Authorization::super($this->p,$u)||Authorization::allowed($this->p,$u,'training.programmes.create',(int)$o))$owners[$o]=$name;if(!$id&&!$owners)throw new \RuntimeException('Tiada scope penciptaan program.');
  $h=self::hidden('programme_id',$id??'').($id?'<p>Pemilik: '.self::e($orgs[$owner]??'').'</p>':self::select('owner_organisation_id','Owner Organisation',$owners,$owner));foreach(['title'=>'Tajuk','organiser'=>'Penganjur','co_organiser'=>'Co-organiser','venue'=>'Tempat / platform'] as $k=>$label)$h.=self::field($k,$label,$c[$k]??'','text',in_array($k,['title','organiser'],true));
  foreach(['type'=>['Jenis',['COURSE','CME','WORKSHOP','SEMINAR','WEBINAR','CONFERENCE']],'classification'=>['Klasifikasi',['NONE','GENERIC','FUNCTIONAL']],'mode'=>['Mod',['PHYSICAL','ONLINE','HYBRID']],'scope'=>['Scope',['INTERNAL','TARGETED','DISTRICT_WIDE']],'registration_mode'=>['Akses pendaftaran',['OPEN','TARGETED','INVITATION_ONLY','ADMIN_ASSIGNED']],'approval_mode'=>['Kelulusan peserta',['AUTO','ADMIN']]] as $k=>[$label,$values])$h.=self::select($k,$label,array_combine($values,$values),$c[$k]??$values[0]);
  $h.=self::field('timezone','Timezone',$c['timezone']??'Asia/Kuala_Lumpur');foreach(['start_at'=>'Mula program','end_at'=>'Tamat program','open_at'=>'Buka pendaftaran','close_at'=>'Tutup pendaftaran'] as $k=>$label){$value=isset($c[$k])?(new \DateTimeImmutable($c[$k],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone($c['timezone']))->format('Y-m-d\TH:i'):'';$h.=self::field($k,$label,$value,'datetime-local');}$h.=self::field('capacity','Kapasiti keseluruhan',$c['capacity']??30,'number').self::field('effective_hours','Jam efektif (maklumat sahaja)',$c['effective_hours']??0,'number').self::field('online_url','Online URL (HTTPS)',$c['online_url']??'','url',false).self::select('coordinator_id','Penyelaras',$this->staffOptions(true),$c['coordinator_id']??'');
  foreach(['waiting_list'=>'Waiting list','walkin_enabled'=>'Walk-in'] as $k=>$label)$h.=self::select($k,$label,['0'=>'Tidak','1'=>'Ya'],$c[$k]??'0');$h.=self::select('audience','Organisasi sasaran (boleh pilih beberapa)',$orgs,$c['audience']??[],true);
  foreach(['profession'=>'Profesion','position'=>'Jawatan','grade'=>'Gred','employment_status'=>'Status perkhidmatan'] as $k=>$label)$h.=self::select($k.'_ids',$label.' layak (kosong: semua)',$this->options('SELECT id,name FROM master_data WHERE category=? AND is_active=1',[$k]),$c['eligibility'][$k]??[],true);
  $h.='<fieldset><legend>Kuota tambahan</legend><p>Gunakan ID organisasi klinik/unit atau ID master profesion yang disenaraikan di bawah. Kuota menghadkan maksimum; tempat pending turut ditempah.</p>';$quotaRows=$c['quotas']??[];for($n=0;$n<max(5,count($quotaRows)+1);$n++){$q=$quotaRows[$n]??[];$h.=self::select('quota_kind[]','Jenis kuota',['clinic'=>'Klinik','unit'=>'Unit','profession'=>'Profesion'],$q['kind']??'').self::field('quota_id[]','ID sasaran',$q['id']??'','number',false).self::field('quota_limit[]','Bilangan maksimum',$q['limit']??'','number',false);}$h.='</fieldset><details><summary>Rujukan ID kuota</summary>';foreach($orgs as $i=>$name)$h.='<p>'.(int)$i.' — '.self::e($name).'</p>';foreach($this->options("SELECT id,name FROM master_data WHERE category='profession'") as $i=>$name)$h.='<p>Profesion '.(int)$i.' — '.self::e($name).'</p>';$h.='</details>';foreach(['objectives'=>'Objektif','target_description'=>'Kumpulan sasaran','tentative'=>'Tentatif'] as $k=>$label)$h.=self::area($k,$label,$c[$k]??'');return self::form('save',$h,'Simpan versi program');
 }
 private function publicPage(int $id,?string $key=null):string {
  $r=Policy::published($this->p,$id);$c=Policy::config($this->p,$r,true);$h='<section class="card"><h2>'.self::e($c['title']).'</h2><p>'.self::e($c['organiser'].' · '.$c['type'].' · '.$c['mode']).'</p><p>'.self::e($c['start_at'].' — '.$c['end_at'].' UTC ('.$c['timezone'].')').'</p><p>'.self::e($c['venue']).'</p><p>'.nl2br(self::e($c['objectives'])).'</p><p>'.nl2br(self::e($c['tentative'])).'</p><p>Pendaftaran: '.self::e($c['registration_mode']).' · Kelulusan: '.self::e($c['approval_mode']).'</p></section>';
  if($this->user){$h.=self::form('register',self::hidden('programme_id',$id).($key?self::hidden('link_key',$key):''),'Daftar program');if($c['walkin_enabled'])$h.=self::form('register',self::hidden('programme_id',$id).self::hidden('walkin','1'),'Daftar walk-in');}else{$h.='<p>Log masuk menggunakan akaun Shared Core untuk mendaftar.</p><a href="/login">Log masuk</a> · <a href="/claim">Claim akaun</a>'; }return $h;
 }
 private function registrationLink():string {$key=Core::text($_GET['key']??$_SESSION['training_pending']['key']??'',32);$r=Tokens::resolve($this->p,$key);return $this->publicPage((int)$r['programme_id'],$key);}
 private function invitationPage():string {$u=$this->actor();$t=$_SESSION['training_pending']['token']??'';if(!preg_match('/\A[a-f0-9]{64}\z/',$t))throw new \RuntimeException('Buka pautan jemputan yang diterima.');$r=Database::query($this->p,'SELECT programme_id FROM training_invitations WHERE token_hash=?',[hash('sha256',$t)])->fetch();if(!$r)throw new \RuntimeException('Jemputan tidak sah.');Tokens::invitation($this->p,$u,(int)$r['programme_id'],$t);return $this->publicPage((int)$r['programme_id']);}
 private function mine():string {$u=$this->actor();$a=Policy::actor($this->p,$u);$h='';foreach(Database::query($this->p,'SELECT * FROM training_registrations WHERE staff_identity_id=? ORDER BY id DESC',[$a['staff_identity_id']])->fetchAll() as $reg){$r=Policy::programme($this->p,(int)$reg['programme_id']);$c=Policy::config($this->p,$r,true);$h.='<section class="card"><h2>'.self::e($c['title']).'</h2><p>'.self::e($reg['status'].' · '.$reg['source']).'</p>'.self::form('decision',self::hidden('programme_id',$r['id']).self::hidden('registration_id',$reg['id']).self::hidden('decision','WITHDRAW').self::field('reason','Sebab tarik diri'),'Tarik diri').'</section>';}return $h?:'<p>Tiada pendaftaran.</p>';}
 private function staffOptions(bool $users=false):array {$u=$this->actor();[$scope,$args]=Authorization::scope($this->p,$u,'core.staff.view','s.organisation_id');return $this->options('SELECT '.($users?'u.id':'s.staff_identity_id').' AS id,s.full_name AS name FROM staff_profiles s '.($users?'JOIN users u ON u.staff_identity_id=s.staff_identity_id AND u.is_active=1 ':'').'WHERE '.$scope.' ORDER BY s.full_name',$args);}
 private function manage(int $id):string {
  $u=$this->actor();$p=$this->p;$r=Policy::programme($p,$id);Policy::require($p,$u,'programmes.view',$r);$c=Policy::config($p,$r);$base=self::hidden('programme_id',$id);$h='<h2>'.self::e($c['title']).'</h2><p>Status: '.self::e($r['status']).' · Versi #'.(int)$r['current_revision_id'].' · Published: '.($r['is_published']?'Ya':'Tidak').'</p><div class="actions"><a href="/training/edit?id='.$id.'">Edit versi</a>'.($r['is_published']?'<a href="/training/p?id='.$id.'">Public page</a>':'').'</div>';
  foreach(['SUBMIT'=>'Hantar semakan','UNDER_REVIEW'=>'Mulakan semakan','APPROVE'=>'Luluskan','RETURN'=>'Pulangkan','REJECT'=>'Tolak','PUBLISH'=>'Terbitkan','UNPUBLISH'=>'Nyahterbit','CANCEL'=>'Batalkan program'] as $decision=>$label)$h.=self::form('transition',$base.self::hidden('revision_id',$r['current_revision_id']).self::hidden('decision',$decision).self::field('reason','Sebab / catatan'),$label);
  if(Policy::allowed($p,$u,'participants.view',$r)){
   $rows=Database::query($p,'SELECT * FROM training_registrations WHERE programme_id=? ORDER BY id',[$id])->fetchAll();$metrics=[];foreach($rows as $row)$metrics[$row['status']]=($metrics[$row['status']]??0)+1;$h.='<h2>Peserta</h2><p>';foreach($metrics as $k=>$v)$h.=self::e($k).': '.$v.' · ';$h.='</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nama / organisasi snapshot</th><th>Status / sumber</th><th>Peranan penyertaan</th><th>Tindakan</th></tr></thead><tbody>';
   foreach($rows as $row){$s=json_decode($row['snapshot_json'],true,512,JSON_THROW_ON_ERROR);$names=Database::query($p,'SELECT rr.name FROM training_participation_assignments a JOIN training_participation_roles rr ON rr.id=a.role_id WHERE a.registration_id=?',[$row['id']])->fetchAll(\PDO::FETCH_COLUMN);$h.='<tr><td>'.(int)$row['id'].'</td><td>'.self::e($s['full_name'].' / '.$s['organisation_name']).'</td><td>'.self::e($row['status'].' / '.$row['source']).'</td><td>'.self::e(implode(', ',$names)).'</td><td>';if(Policy::allowed($p,$u,'participants.manage',$r))foreach(['APPROVE'=>'Luluskan peserta','REJECT'=>'Tolak peserta','WITHDRAW'=>'Tarik keluar'] as $a=>$label)$h.=self::form('decision',$base.self::hidden('registration_id',$row['id']).self::hidden('decision',$a).self::field('reason','Sebab'),$label);$h.='</td></tr>';}$h.='</tbody></table></div>';
  }
  if(Policy::allowed($p,$u,'participants.assign',$r)){$staff=$this->staffOptions();$h.='<h2>Assignment individu / bulk</h2>'.self::form('assign',$base.self::select('staff_ids','Pilih staf',$staff,[],true),'Assign staf terpilih').self::form('walkin_assign',$base.self::select('staff_identity_id','Staf walk-in',$staff),'Daftar walk-in').'<h2>Import assignment CSV</h2><p>Header: official_email. Staf mesti wujud dalam Shared Registry. Preview mengesan duplicate, scope dan kelayakan; commit menyemak semula kuota.</p>'.self::form('preview',$base.self::field('file','Fail CSV','','file'),'Preview',true);$batch=$_SESSION['training_import']??null;if($batch&&$batch['programme']===$id){$h.='<pre>'.self::e(json_encode($batch['rows'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>'.self::form('import_commit',$base,'Import baris sah');}$result=$_SESSION['training_import_result']??null;if($result)$h.='<h3>Laporan assignment</h3><pre>'.self::e(json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';}
  if(Policy::allowed($p,$u,'invitations.manage',$r)){$h.='<h2>Jemputan</h2>'.self::form('invite',$base.self::select('staff_identity_id','Staf dijemput',$this->staffOptions()),'Queue jemputan');if(isset($_SESSION['training_invite_url'])){$h.='<p>Pautan terakhir: '.self::e($_SESSION['training_invite_url']).'</p>';unset($_SESSION['training_invite_url']);}foreach(Database::query($p,'SELECT id,staff_identity_id,expires_at,used_at,revoked_at FROM training_invitations WHERE programme_id=? ORDER BY id DESC',[$id])->fetchAll() as $i)$h.='<p>Jemputan #'.$i['id'].' · '.self::e($i['expires_at']).'</p>'.self::form('invite_revoke',$base.self::hidden('invitation_id',$i['id']),'Batalkan jemputan');}
  if(Policy::allowed($p,$u,'links.manage',$r)){$h.='<h2>Pautan & QR pendaftaran</h2>'.self::form('link',$base,'Jana / rotate link');$key=Database::query($p,'SELECT public_key FROM training_links WHERE programme_id=? AND revoked_at IS NULL ORDER BY id DESC LIMIT 1',[$id])->fetchColumn();if($key)$h.='<p><a href="/training/register?key='.self::e($key).'">'.self::e(Accounts::origin().'/training/register?key='.$key).'</a></p><img width="240" height="240" alt="QR pautan pendaftaran" src="/training/qr?key='.self::e($key).'">';}
  if(Policy::allowed($p,$u,'roles.manage',$r)){$roles=$this->options("SELECT id,name FROM roles WHERE module_code='training' AND code IN ('training_programme_admin','training_approver') AND is_active=1");$h.='<h2>Akses pentadbiran program sementara</h2>'.self::form('grant',$base.self::select('user_id','Pengguna',$this->staffOptions(true)).self::select('role_id','Role akses',$roles).self::field('expires_at','Tamat (UTC YYYY-MM-DD HH:MM:SS)',gmdate('Y-m-d H:i:s',time()+7*86400)).self::field('reason','Sebab'),'Berikan akses');foreach(Database::query($p,'SELECT a.*,s.full_name,r.name FROM training_access_assignments a JOIN users u ON u.id=a.user_id JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id JOIN roles r ON r.id=a.role_id WHERE a.programme_id=?',[$id])->fetchAll() as $a)$h.='<p>'.self::e($a['full_name'].' · '.$a['name'].' · '.$a['expires_at']).'</p>'.self::form('revoke',$base.self::hidden('assignment_id',$a['id']).self::field('reason','Sebab'),'Revoke');}
  if(Policy::allowed($p,$u,'participants.manage',$r))$h.='<h2>Peranan penyertaan (boleh serentak)</h2>'.self::form('role_define',$base.self::field('code','Kod role').self::field('name','Nama role'),'Simpan role penyertaan').self::form('participation',$base.self::field('registration_id','Registration ID','','number').self::select('role_id','Role penyertaan',$this->options('SELECT id,name FROM training_participation_roles WHERE programme_id=? AND is_active=1',[$id])).self::select('remove','Tindakan',['0'=>'Assign','1'=>'Revoke'],'0'),'Simpan peranan');
  if(Policy::allowed($p,$u,'documents.upload',$r))$h.='<h2>Dokumen program</h2>'.self::form('document',$base.self::field('title','Tajuk dokumen').self::field('document_id','Document ID untuk versi baharu','','number',false).self::field('file','PDF/JPEG/PNG, maksimum 5MB','','file'),'Upload',true);
  foreach(Database::query($p,'SELECT d.id,d.title,MAX(v.version) AS version FROM training_programme_documents a JOIN documents d ON d.id=a.document_id JOIN document_versions v ON v.document_id=d.id WHERE a.programme_id=? GROUP BY d.id,d.title',[$id])->fetchAll() as $d)$h.='<p><a href="/download?id='.$d['id'].'&version='.$d['version'].'">'.self::e($d['title']).'</a></p>';return '<p><a href="/training/workstation?id='.$id.'">Module 1 Workstation</a></p>'.$h;
 }
}
